package vn.rtr.aeris.shell29;
import java.nio.file.*;import java.util.*;import java.nio.charset.StandardCharsets;import vn.rtr.aeris.shell24.VideoModel;
public final class WorkflowTest {
 static int count=0;static long t=0;static void ok(String name,boolean v){if(!v)throw new AssertionError(name);System.out.println("PASS "+name);count++;}
 interface Job{void go()throws Exception;}static void refuses(String n,Job j){boolean refused=false;try{j.go();}catch(Exception e){refused=true;}ok(n,refused);}
 static Workflow ready(){t=100;Workflow w=new Workflow("mock:flow");w.focus(true,t);w.navigate("Preflight",t);w.inspect(w.fixture(t),t);w.confirmHome(t);w.confirmAltitude(t);w.navigate("Fly",t);return w;}
 static void complete(Workflow w){while(w.phase().equals("RUNNING_MOCK"))w.step(++t);w.land(++t);}
 public static void main(String[] a)throws Exception{
  for(int i=0;i<Catalog.COUNT;i++){Plan p=Catalog.get(i);ok("compiled catalog hash "+i,p.sha.equals(Plan.hash(p.compiledRaw))&&p.points()>1&&p.altitudeM>=60);double[][] copy=p.route();copy[0][0]+=100;ok("immutable route "+i,p.route()[0][0]!=copy[0][0]);}
  ok("Home projection differs from shifted polygon centroid",Math.abs(Catalog.get(2).homeX+3.75)<.01&&Math.abs(Catalog.get(2).homeY+7.5)<.01);
  refuses("unknown plan index",()->Catalog.get(6));Workflow w=new Workflow("mock:flow");ok("no start without preflight",!w.start(0));w.focus(true,0);ok("Home confirmation requires observation",!w.confirmHome(0));ok("altitude confirmation requires observation",!w.confirmAltitude(0));
  w=ready();ok("current preflight ready",w.ready(t));ok("start mock run",w.start(t));w.ack(++t);ok("ACK alone neither progress nor completion",w.cursor()==0&&w.phase().equals("RUNNING_MOCK"));ok("landing before route is refused",!w.land(++t));final Workflow running=w;refuses("plan locked during active mock run",()->running.select(2,++t));complete(w);ok("completion requires mock landing",w.phase().equals("COMPLETED_MOCK")&&w.review().contains("MOCK_LANDING_OBSERVED"));ok("review never real media/flight",w.review().contains("\"physicalMediaVerified\":false")&&w.review().contains("\"flightExecutionProven\":false")&&w.review().contains("\"media\":[]"));
  w=ready();w.navigate("Plan",t);ok("ready alone cannot start outside Fly",!w.start(t));w.select(2,++t);ok("plan revision invalidates gates",!w.ready(t)&&w.revision()==2);
  w=ready();ok("preflight expires",!w.ready(t+30001));
  Workflow missing=new Workflow("mock:missing");missing.focus(true,0);ok("missing observation never fills manufacturer defaults",!missing.inspect(new Workflow.Observation(),0));
  for(String kind:new String[]{"session","generation","revision","mission","readback","profile","datum","home","firmware","parameters","future","unknown","armed","nonmock"}){
   Workflow x=new Workflow("mock:flow");x.focus(true,100);Workflow.Observation o=x.fixture(100);
   switch(kind){case "session":o.session="old";break;case "generation":o.generation=2;break;case "revision":o.revision=2;break;case "mission":o.planSha="bad";break;case "readback":o.readbackSha="bad";break;case "profile":o.profileSha="bad";break;case "datum":o.datum="terrain";break;case "home":o.amsl=11;break;case "firmware":o.firmware="4.7.2";break;case "parameters":o.options=0;break;case "future":o.at=101;break;case "unknown":o.lat=Double.NaN;break;case "armed":o.disarmed=false;break;case "nonmock":o.synthetic=false;break;}
   ok("preflight refuses "+kind,!x.inspect(o,100)&&!x.start(100));
  }
  w=ready();w.start(t);w.step(++t);int c=w.cursor();w.focus(false,++t);ok("focus suspends UI without aircraft HOLD",w.phase().equals("UI_SUSPENDED_MOCK")&&w.review().contains("UI_FOCUS_LOST_NOT_AIRCRAFT_HOLD"));w.focus(true,++t);ok("resume never automatic",w.cursor()==c&&!w.resume(t));w.inspect(w.fixture(++t),t);w.confirmHome(t);w.confirmAltitude(t);ok("explicit recheck and resume",w.resume(t)&&w.cursor()==c);
  w=ready();w.start(t);long g=w.generation();w.disconnect(++t);ok("loss preserves interruption/new generation",w.phase().equals("INTERRUPTED_LINK_LOSS")&&w.generation()==g+1);w.connect(++t);ok("reconnect does not resume old run",!w.resume(t)&&!w.ready(t));
  w=ready();w.start(t);Workflow.Observation changed=w.fixture(++t);changed.amsl=11;ok("active mismatch interrupts mock run",!w.inspect(changed,t)&&w.phase().equals("INTERRUPTED_PREFLIGHT_CHANGED"));ok("changed preflight cannot complete old run",!w.step(++t)&&!w.land(t));
  w=ready();w.start(t);w.disconnect(++t);w.mockNeutral(t+=10);t+=100;ok("no owner after link loss before explicit connect",!w.acquire("GIMBAL_FRONT",t));ok("disconnected preflight cannot self-validate",!w.inspect(w.fixture(++t),t));
  w=ready();w.start(t);w.reboot(++t);ok("reboot invalidates preflight/run",w.phase().equals("INTERRUPTED_MOCK_AIRCRAFT_REBOOT")&&!w.ready(t));
  final Workflow clock=ready();clock.start(t);refuses("clock regression freezes run",()->clock.step(t-1));ok("clock regression not completion",clock.phase().equals("INTERRUPTED_CLOCK_REGRESSION"));
  w=ready();w.start(t);w.mockNeutral(t+=10);t+=100;ok("manual owner refused outside mock HOLD",!w.acquire("MANUAL_AIRCRAFT",t));ok("gimbal explicit mock owner",w.acquire("GIMBAL_FRONT",t));ok("selection never retargets owner",!w.acquire("GIMBAL_CENTER",t)&&w.input.owner().equals("NONE"));w.mockNeutral(t+=10);t+=100;w.hold(t);w.mockNeutral(t+=10);t+=100;ok("manual owner allowed only after HOLD/neutral",w.acquire("MANUAL_AIRCRAFT",t));w.focus(false,++t);ok("focus releases input owner",w.input.owner().equals("NONE"));
  w=ready();w.mockNeutral(t+=10);t+=100;ok("foreign input session refused",!w.input.sample("other",w.generation(),"mock:joystick",1,t+50));ok("foreign input generation refused",!w.input.sample(w.session,w.generation()+1,"mock:joystick",1,t+50));ok("foreign device refused",!w.input.sample(w.session,w.generation(),"mock:other",1,t+50));t+=50;w.acquire("GIMBAL_FRONT",t);w.input.tick(t+251);ok("stale input loses owner",w.input.owner().equals("NONE"));
  w=ready();w.mockNeutral(t+=10);t+=100;ok("explicit center owner after neutral",w.acquire("GIMBAL_CENTER",t)&&w.input.owner().equals("GIMBAL_CENTER"));
  w=ready();w.mockNeutral(t+=10);t+=100;w.acquire("GIMBAL_FRONT",t);w.input.detach(++t);ok("hotplug releases owner",w.input.owner().equals("NONE"));
  VideoModel v=new VideoModel();String hash=String.join("",Collections.nCopies(64,"a"));v.select("SYNTHETIC_FIXTURE",hash,100,0);long vg=v.prepare(1);ok("wrong video generation refused",!v.prepared(vg-1,640,360,1500,2));ok("mock video metadata prepared",v.prepared(vg,640,360,1500,2));ok("mock video explicit play",v.play(vg,3));v.stop("FOCUS_LOST");ok("old render callback cannot restart",!v.rendered(vg,4));ok("video never guesses physical latency",v.json().contains("\"frameAgeMs\":null")&&v.json().contains("\"cameraToDisplayLatencyMs\":null"));
  final VideoModel invalid=new VideoModel();refuses("unverified video origin",()->invalid.select("REAL_CAMERA",hash,100,0));
  w=ready();for(int i=0;i<300;i++)w.inspect(w.fixture(++t),t);ok("journal bound discloses incomplete",!w.evidenceComplete()&&w.events().size()==Workflow.MAX_EVENTS);ok("incomplete evidence refuses completion/start",!w.start(t)&&!w.land(t));
  Path root=Paths.get(a[0]);HistoryStore store=new HistoryStore(root);Workflow historical=ready();historical.start(t);complete(historical);byte[] bytes=historical.review().getBytes(StandardCharsets.UTF_8);String digest=store.save(bytes);ok("host immutable history SHA",Arrays.equals(store.read(digest),bytes));ok("identical snapshot coalesces",store.save(bytes).equals(digest)&&store.list().size()==1);Workflow fresh=new Workflow("new:session");ok("restart never restores run/input/video",fresh.phase().equals("DRAFT")&&fresh.input.owner().equals("NONE")&&fresh.video.state.equals("EMPTY"));
  Files.write(root.resolve(digest+".json"),"corrupt".getBytes(StandardCharsets.UTF_8));refuses("corrupt history refused",()->store.read(digest));ok("corrupt evidence retained",Files.exists(root.resolve(digest+".json")));
  refuses("history path traversal",()->store.read("../history"));refuses("oversize historical snapshot",()->store.save(new byte[HistoryStore.MAX_BYTES+1]));
  byte[] pending="unique pending".getBytes(StandardCharsets.UTF_8);String pd=Plan.hash(pending);Files.write(root.resolve(pd+".pending"),"old pending".getBytes(StandardCharsets.UTF_8));refuses("prior pending file not overwritten",()->store.save(pending));ok("prior pending receipt retained",new String(Files.readAllBytes(root.resolve(pd+".pending")),StandardCharsets.UTF_8).equals("old pending"));
  for(int i=1;i<32;i++)store.save(("history "+i).getBytes(StandardCharsets.UTF_8));refuses("history quota blocks without auto deletion",()->store.save("over quota".getBytes(StandardCharsets.UTF_8)));ok("quota retains32historical receipts",store.list().size()==32);
  System.out.println("TOTAL "+count);
 }
}
